import os,json
def transform(grid):
    h,w=len(grid),len(grid[0]); g=[r[:] for r in grid]
    seen=set(); objs=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                c=g[i][j]; st=[(i,j)]; comp=set()
                while st:
                    y,x=st.pop()
                    if (y,x) in comp or not(0<=y<h and 0<=x<w) or g[y][x]!=c: continue
                    comp.add((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)): st.append((y+dy,x+dx))
                seen|=comp
                if len(comp)>1: objs.append((c,comp))
    def norm(comp):
        ys=[y for y,x in comp]; xs=[x for y,x in comp]
        return tuple(sorted((y-min(ys),x-min(xs)) for y,x in comp))
    # key: L-shaped object (cells in exactly one row-arm and one col-arm) with unique shape; use largest L
    def isL(comp):
        ys=[y for y,x in comp]; xs=[x for y,x in comp]
        H=max(ys)-min(ys)+1; W=max(xs)-min(xs)+1
        corner=[(min(ys),min(xs)),(min(ys),max(xs)),(max(ys),min(xs)),(max(ys),max(xs))]
        return any(c in comp for c in corner) and len(comp)==H+W-1 and H>1 and W>1
    Ls=[(c,comp) for c,comp in objs if isL(comp)]
    # key = L whose norm shape is unique among all objects
    from collections import Counter
    cnt=Counter(norm(c) for _,c in objs)
    keys=[(len(c),c,col) for col,c in Ls if cnt[norm(c)]==1]
    keys.sort()
    kc,kcomp,kcol=keys[-1]
    # duplicate groups
    groups={}
    for c,comp in objs:
        groups.setdefault(norm(comp),[]).append((c,comp))
    for shape,members in groups.items():
        if len(members)<2 or shape==norm(kcomp): continue
        def d(comp):
            return min(abs(y-ky)+abs(x-kx) for y,x in comp for ky,kx in kcomp)
        members.sort(key=lambda m:d(m[1]))
        for c,comp in members[:-1]:
            for y,x in comp: g[y][x]=kcol
    return g
